 8931 func (gs *GameState) DrawCardWithEvent(playerIdx int) error {
 8932 	player := gs.GetPlayer(playerIdx)
 8933 	if player == nil {
 8934 		return errors.New("invalid player")
 8935 	}
 8936 
 8937 	if gs.ReplacementManager != nil {
 8938 		if effect := gs.ReplacementManager.GetDrawReplacement(playerIdx); effect != nil {
 8939 			return effect.DrawReplacementFn(gs, playerIdx)
 8940 		}
 8941 	}
 8942 
 8943 	// Get the card that will be drawn (peek at top)
 8944 	topCards, err := player.Library.LookAtTop(1)
 8945 	if err != nil || len(topCards) == 0 {
 8946 		return errors.New("cannot draw from empty library")
 8947 	}
 8948 	drawnCard := topCards[0]
 8949 
 8950 	// Actually draw the card
 8951 	if err := player.DrawCard(); err != nil {
 8952 		return err
 8953 	}
 8954 
 8955 	// Fire draw event
 8956 	if gs.EventBus != nil {
 8957 		triggered := gs.EventBus.Publish(CreateDrawEvent(drawnCard, playerIdx))
 8958 		for _, ability := range triggered {
 8959 			gs.PutTriggeredAbilityOnStack(ability)
 8960 		}
 8961 	}
 8962 
 8963 	return nil
 8964 }

